INSERT INTO "blocks" ("block_id", "parent_block_id", "parent_page_id", "type", "content_json", "has_children", "archived", "position", "created_time", "last_edited_time") VALUES ('blk_c529g_7t2swhdpk', NULL, 'pg_c529g_nxr8d92m', 'paragraph', '{"rich_text":[{"type":"text","text":{"content":"Housing Support — Checklist records a dated business fact: The summer guest quote and spring allowance are retained as nearby but inapplicable records. A copy is with the supporting file."}}]}', 0, 0, 30027, '2026-05-07T12:36:00Z', '2026-05-27T11:48:00Z');
INSERT INTO "blocks" ("block_id", "parent_block_id", "parent_page_id", "type", "content_json", "has_children", "archived", "position", "created_time", "last_edited_time") VALUES ('blk_c529g_k5n9v637u', NULL, 'pg_c529g_nxr8d92m', 'paragraph', '{"rich_text":[{"type":"text","text":{"content":"Household note for Housing Support — Checklist: The housing file keeps issued invoices, estimates, and unsigned quotes under distinct document statuses. A copy is with the supporting file."}}]}', 0, 0, 30046, '2026-05-14T13:05:00Z', '2026-05-24T13:05:00Z');
INSERT INTO "blocks" ("block_id", "parent_block_id", "parent_page_id", "type", "content_json", "has_children", "archived", "position", "created_time", "last_edited_time") VALUES ('blk_c529g_b38fkfr7f', NULL, 'pg_c529g_nvwxnw5a', 'paragraph', '{"rich_text":[{"type":"text","text":{"content":"At the 2026-06-10 close, the June 10 invoice identifies standard room rent and the required residence meal plan as separate billed lines. A copy is with the supporting file."}}]}', 0, 0, 31088, '2026-05-21T14:34:00Z', '2026-06-10T12:22:00Z');
INSERT INTO "blocks" ("block_id", "parent_block_id", "parent_page_id", "type", "content_json", "has_children", "archived", "position", "created_time", "last_edited_time") VALUES ('blk_c529g_j4zxyz9mu', NULL, 'pg_c529g_nvwxnw5a', 'paragraph', '{"rich_text":[{"type":"text","text":{"content":"Supporting record under Housing Support — Calculation. Parking, furniture rental, premium services, and the security deposit are separately labeled on the invoice. A copy is with the supporting file."}}]}', 0, 0, 31108, '2026-05-28T15:03:00Z', '2026-06-09T17:03:00Z');
INSERT INTO "blocks" ("block_id", "parent_block_id", "parent_page_id", "type", "content_json", "has_children", "archived", "position", "created_time", "last_edited_time") VALUES ('blk_c529g_mdebkdesb', NULL, 'pg_c529g_rqryqu47', 'paragraph', '{"rich_text":[{"type":"text","text":{"content":"The ledger entry associated with Housing Support — Follow-up states: The Campus Lofts comparison quote predates the itemized invoice and bundles optional services with base rent. A copy is with the supporting file."}}]}', 0, 0, 32054, '2026-06-04T08:32:00Z', '2026-06-14T22:00:00Z');
INSERT INTO "blocks" ("block_id", "parent_block_id", "parent_page_id", "type", "content_json", "has_children", "archived", "position", "created_time", "last_edited_time") VALUES ('blk_c529g_tw3h7db6j', NULL, 'pg_c529g_rqryqu47', 'paragraph', '{"rich_text":[{"type":"text","text":{"content":"Document status in Housing Support — Follow-up: The unsigned comparison quote has no accepted-contract status in the household file. A copy is with the supporting file."}}]}', 0, 0, 32075, '2026-01-07T09:01:00Z', '2026-06-06T13:13:00Z');
INSERT INTO "blocks" ("block_id", "parent_block_id", "parent_page_id", "type", "content_json", "has_children", "archived", "position", "created_time", "last_edited_time") VALUES ('blk_c529g_sqxz7g4f6', NULL, 'pg_c529g_b2ez7bnb', 'paragraph', '{"rich_text":[{"type":"text","text":{"content":"Reconciliation note dated 2026-01-29. Oak Terrace rent activity is household housing cashflow and is not the Northlake Fall 2026 invoice. A copy is with the supporting file."}}]}', 0, 0, 33022, '2026-01-14T10:30:00Z', '2026-01-29T10:30:00Z');
INSERT INTO "blocks" ("block_id", "parent_block_id", "parent_page_id", "type", "content_json", "has_children", "archived", "position", "created_time", "last_edited_time") VALUES ('blk_c529g_9x9rvvzrt', NULL, 'pg_c529g_b2ez7bnb', 'paragraph', '{"rich_text":[{"type":"text","text":{"content":"For Housing Support — Archive, the retained source shows that the June 22 bursar review and the housing invoice review are separate calendar entries. A copy is with the supporting file."}}]}', 0, 0, 33044, '2026-01-21T11:59:00Z', '2026-06-14T13:47:00Z');
INSERT INTO "blocks" ("block_id", "parent_block_id", "parent_page_id", "type", "content_json", "has_children", "archived", "position", "created_time", "last_edited_time") VALUES ('blk_c529g_pakdamjzm', NULL, 'pg_c529g_2t9kq7xe', 'paragraph', '{"rich_text":[{"type":"text","text":{"content":"Business context preserved in Housing Support — Boundary: The $13,250 Tuition Reserve Bucket is recorded separately from checking and household housing payments. A copy is with the supporting file."}}]}', 0, 0, 34089, '2026-01-28T12:28:00Z', '2026-02-14T14:28:00Z');
